// Shape of the neighbour and distance files generated by `npm run data` (scripts/proximity.mjs).

/** neighbors.json: land borders, from the topology of the map. */
export interface NeighborsData {
  world: {
    /** Territories off: a territory counts as the country that administers it. */
    territoriesOff: Record<string, string[]>;
    /** Territories on: each territory has neighbours of its own. */
    territoriesOn: Record<string, string[]>;
    /** Borders that exist only through territories (off): "BRA|FRA" (ids in order) → ["GUF"]. */
    via: Record<string, string[]>;
    /** Trail game (territories off): a border through a territory counts only on the same continent. */
    trail: Record<string, string[]>;
    /** Trail game (territories on): territoriesOn without the borders excluded by hand. */
    trailTerritories: Record<string, string[]>;
  };
  /** Brazilian states, by abbreviation. */
  brazil: Record<string, string[]>;
}

/** proximity-*.json: distances and directions between every pair of places. */
export interface ProximityData {
  ids: string[];
  /** Km between the nearest edges, for each pair i < j, row by row (0 = neighbours). */
  km: number[];
  /** `dir[i][j]`: hex digit of the compass sector (0 = N, 4 = E, 8 = S, c = W) from i to j. */
  dir: string[];
}

/** The key of a pair in `via`: the two ids in alphabetical order. */
export const pairKey = (a: string, b: string): string => (a < b ? `${a}|${b}` : `${b}|${a}`);

/** Km between the nearest edges of two different places. */
export function distanceKm(data: ProximityData, a: string, b: string): number {
  const n = data.ids.length;
  const i = Math.min(data.ids.indexOf(a), data.ids.indexOf(b));
  const j = Math.max(data.ids.indexOf(a), data.ids.indexOf(b));
  return data.km[(i * (2 * n - i - 1)) / 2 + (j - i - 1)];
}

/**
 * Distance shown on screen: 0 (neighbours) stays 0, anything else is rounded to tens of km, at
 * least 10 ("≈ 10 km"). The data come from a simplified map, so they are approximate.
 */
export function approxKm(km: number): number {
  return km === 0 ? 0 : Math.max(10, Math.round(km / 10) * 10);
}

/** Compass sector (0-15, 0 = north, clockwise) from place `from` towards place `to`. */
export function directionSector(data: ProximityData, from: string, to: string): number {
  return parseInt(data.dir[data.ids.indexOf(from)][data.ids.indexOf(to)], 16);
}
